import React, { useState, useEffect } from 'react';
import { getAllRuns, exportCSV } from '../api';
import { useNavigate } from 'react-router-dom';
import './AdminDashboard.css';

function AdminDashboard({ user, onLogout }) {
  const [users, setUsers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [downloading, setDownloading] = useState(false);
  const navigate = useNavigate();

  useEffect(() => {
    loadUserStats();
  }, []);

  const loadUserStats = async () => {
    try {
      setLoading(true);
      const runs = await getAllRuns();
      
      // Group runs by user
      const userMap = {};
      runs.forEach(run => {
        const userId = run.user_id || 'unknown';
        if (!userMap[userId]) {
          userMap[userId] = {
            user_id: userId,
            username: run.username || 'Unknown User',
            total_prompts: 0,
            scores: [],
            last_active: null
          };
        }
        
        userMap[userId].total_prompts += 1;
        if (run.predicted_score) {
          userMap[userId].scores.push(run.predicted_score);
        }
        
        const runDate = new Date(run.created_at);
        if (!userMap[userId].last_active || runDate > new Date(userMap[userId].last_active)) {
          userMap[userId].last_active = run.created_at;
        }
      });
      
      // Calculate average scores
      const userList = Object.values(userMap).map(u => ({
        ...u,
        avg_score: u.scores.length > 0 
          ? (u.scores.reduce((a, b) => a + b, 0) / u.scores.length).toFixed(3)
          : 'N/A'
      }));
      
      setUsers(userList);
    } catch (error) {
      console.error('Failed to load user stats:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleDownloadCSV = async () => {
    try {
      setDownloading(true);
      const data = await exportCSV();
      
      // Create blob and download
      const blob = new Blob([data.csv || data], { type: 'text/csv' });
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `mas_data_${new Date().toISOString().split('T')[0]}.csv`;
      document.body.appendChild(a);
      a.click();
      window.URL.revokeObjectURL(url);
      document.body.removeChild(a);
    } catch (error) {
      console.error('Failed to download CSV:', error);
      alert('Failed to download CSV');
    } finally {
      setDownloading(false);
    }
  };

  const handleUserClick = (userId) => {
    navigate(`/admin/user/${userId}`);
  };

  const getActivityStatus = (lastActive) => {
    if (!lastActive) return 'never';
    const diff = Date.now() - new Date(lastActive).getTime();
    const hours = diff / (1000 * 60 * 60);
    
    if (hours < 1) return 'active';
    if (hours < 24) return 'recent';
    if (hours < 168) return 'week';
    return 'old';
  };

  return (
    <div className="dashboard-container">
      <header className="dashboard-header">
        <h1>Admin Dashboard</h1>
        <div className="user-info">
          <span>Welcome, {user.username} (Admin)</span>
          <button onClick={onLogout}>Logout</button>
        </div>
      </header>

      <div className="admin-content">
        <div className="stats-section">
          <div className="stat-card">
            <h3>Total Runs</h3>
            <p className="stat-value">{runs.length}</p>
          </div>
          <div className="stat-card">
            <h3>Average Score</h3>
            <p className="stat-value">
              {runs.length > 0 
                ? (runs.reduce((sum, r) => sum + r.predicted_score, 0) / runs.length).toFixed(2)
                : 'N/A'}
            </p>
          </div>
          <div className="stat-card">
            <h3>Unique Users</h3>
            <p className="stat-value">
              {new Set(runs.map(r => r.username)).size}
            </p>
          </div>
          <div className="stat-card">
            <button className="export-button" onClick={handleExport}>
              Export CSV
            </button>
          </div>
        </div>

        <div className="runs-table-section">
          <h2>All Runs</h2>
          {loading ? (
            <p className="loading">Loading...</p>
          ) : (
            <div className="table-container">
              <table className="runs-table">
                <thead>
                  <tr>
                    <th>User</th>
                    <th>Task</th>
                    <th>Score</th>
                    <th>Date</th>
                    <th>Action</th>
                  </tr>
                </thead>
                <tbody>
                  {runs.map((run) => (
                    <tr key={run._id}>
                      <td>{run.username}</td>
                      <td className="task-cell">{run.task.substring(0, 50)}...</td>
                      <td>{run.predicted_score.toFixed(2)}</td>
                      <td>{new Date(run.created_at).toLocaleDateString()}</td>
                      <td>
                        <button 
                          className="view-button"
                          onClick={() => setSelectedRun(run)}
                        >
                          View
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
              {runs.length === 0 && (
                <p className="no-data">No runs available</p>
              )}
            </div>
          )}
        </div>
      </div>

      {selectedRun && (
        <div className="modal" onClick={() => setSelectedRun(null)}>
          <div className="modal-content" onClick={(e) => e.stopPropagation()}>
            <h3>Run Details</h3>
            <div className="detail-row">
              <strong>User:</strong> {selectedRun.username}
            </div>
            <div className="detail-row">
              <strong>Run ID:</strong> {selectedRun._id}
            </div>
            <div className="detail-row">
              <strong>Predicted Score:</strong> {selectedRun.predicted_score.toFixed(2)}
            </div>
            <div className="detail-row">
              <strong>Date:</strong> {new Date(selectedRun.created_at).toLocaleString()}
            </div>
            <div className="detail-section">
              <strong>Task:</strong>
              <p>{selectedRun.task}</p>
            </div>
            {selectedRun.code && (
              <div className="detail-section">
                <strong>Generated Code:</strong>
                <pre className="code-block">{selectedRun.code}</pre>
              </div>
            )}
            <div className="detail-section">
              <strong>Features:</strong>
              <div className="features-grid">
                {Object.entries(selectedRun.features || {}).map(([key, value]) => (
                  <div key={key} className="feature-item">
                    <span className="feature-name">{key.replace(/_/g, ' ')}:</span>
                    <span className="feature-value">
                      {typeof value === 'number' ? value.toFixed(2) : value}
                    </span>
                  </div>
                ))}
              </div>
            </div>
            <button onClick={() => setSelectedRun(null)}>Close</button>
          </div>
        </div>
      )}
    </div>
  );
}

export default AdminDashboard;
